        for fname in os.listdir(expdir):
            fpath = os.path.join(expdir, fname)
            if not os.path.isfile(fpath):
                continue
            # try JSON
            if fname.lower().endswith(".json"):
                try:
                    j = json.load(open(fpath,"r",encoding="utf-8"))
                    if is_timed_from_json(j):
                        timed = True
                        break
                except Exception:
                    # fallback to text search
                    if check_file_for_timeout(fpath):
                        timed = True
                        break
            else:
                if check_file_for_timeout(fpath):
                    timed = True
                    break
        if timed:
            timeouts[n] += 1

# format percentages with ROUND_HALF_UP
def fmt_percent(n, num, den):
    if den == 0:
        val = Decimal('0')
    else:
        val = Decimal(num) * Decimal('100') / Decimal(den)
    if 8 <= n <= 13:
        q = Decimal('0.1')
        v = val.quantize(q, rounding=ROUND_HALF_UP)
        s = format(v, 'f')
        # ensure one decimal place
        if '.' not in s:
            s = s + '.0'
        else:
            # one decimal
            parts = s.split('.')
            s = parts[0]+'.'+(parts[1]+'0')[:1]
        return s
    elif n in (14,15):
        q = Decimal('0.1')
        v = val.quantize(q, rounding=ROUND_HALF_UP)
        s = format(v, 'f')
